macro.command:
const pass = args[0].macroPass;
const caster = macroItem.actor;
const combat = game.combat;

if (pass === "postActiveEffects" && workflow.item.uuid === macroItem.uuid) {
  const types = ["acid", "cold", "fire", "lightning", "thunder"];
  const incoming = [...new Set((workflow.workflowOptions.damageDetail ?? [])
    .filter(d => types.includes(d.type) && (d.value ?? d.damage) > 0).map(d => d.type))];
  const damageType = incoming.length === 1 ? incoming[0]
    : await dnd5eClasspack.dialogUtils.selectDamageType(
      incoming.length ? incoming : types, macroItem.name, "",
      { userId: dnd5eClasspack.firstOwner(caster, true) }
    );
  if (!damageType) return;

  const index = combat?.started ? combat.turns.findIndex(c => c.tokenId === workflow.tokenId) : -1;
  const turn = index < 0 ? null
    : `${combat.id}:${combat.round + (index <= combat.turn ? 1 : 0)}:${index}`;
  const ownTurn = combat?.started && combat.combatant?.tokenId === workflow.tokenId;
  const label = game.i18n.localize(CONFIG.DND5E.damageTypes[damageType].label);
  const cast = workflow.itemCardUuid;

  await caster.createEmbeddedDocuments("ActiveEffect", [{
    name: `${macroItem.name}：${label}抗性`, type: "base", img: macroItem.img,
    system: {
      origin: { item: macroItem.uuid, message: cast },
      changes: [{ key: "system.traits.dr.value", value: damageType,
        type: "add", phase: "initial", priority: 20 }]
    },
    duration: combat?.started ? { expiry: "targetStart" } : { value: 6, units: "seconds" },
    flags: { dae: { stackable: "noneName" }, world: { absorbElementsResistance: cast } }
  }, {
    name: `${macroItem.name}：储能`, type: "base", img: macroItem.img,
    system: {
      origin: { item: macroItem.uuid, message: cast },
      changes: [{ key: "flags.midi-qol.onUseMacroName",
        value: `[postDamageRoll]ItemMacro.${macroItem.uuid}`,
        type: "add", phase: "initial", priority: 20 }]
    },
    // 自己回合中施法时，跨过当前回合末，保留到下一回合末。
    duration: combat?.started
      ? { expiry: "targetEnd", ...(ownTurn ? { value: 1, units: "rounds" } : {}) }
      : { value: 12, units: "seconds" },
    flags: {
      dae: { stackable: "noneName" },
      world: { absorbElements: { damageType, dice: workflow.spellLevel, turn, cast } }
    }
  }]);
  return;
}

if (pass !== "postDamageRoll" || workflow.activity.type !== "attack" || !workflow.hitTargets.size
  || !["mwak", "msak"].includes(workflow.activity.getActionType(workflow.attackMode))) return;

const effect = caster.effects.find(e => e.active && e.getFlag("world", "absorbElements"));
if (!effect) return;
const state = effect.getFlag("world", "absorbElements");
if (combat?.started && state.turn && state.turn !== `${combat.id}:${combat.round}:${combat.turn}`) return;

const primary = workflow.damageRolls[0];
const roll = await new CONFIG.Dice.DamageRoll(`${state.dice}d6`, {}, {
  type: state.damageType, types: [state.damageType], properties: ["mgc", "spell"],
  flavor: macroItem.name, isCritical: primary.isCritical,
  critical: { ...primary.options.critical, bonusDice: 0, bonusDamage: "" }
}).evaluate();
await workflow.setDamageRolls([...workflow.damageRolls, roll]);
await caster.deleteEmbeddedDocuments("ActiveEffect", caster.effects
  .filter(e => e.id === effect.id || e.getFlag("world", "absorbElementsResistance") === state.cast)
  .map(e => e.id));
